"""Opt-in grouped side counts for the ordinary corner-pattern source layout.

Only the small count table is replaced. Original knots and all consumers remain
unchanged. This experiment needs native equivalence and timing qualification
before being used by an asset recipe.
"""
import hashlib

import bpy

from . import curved_multisided_quad_nodes as cyclic
from .curved_quad_fair_nodes import assign_group

c = cyclic.c


def supports(tree):
    return (tree.name.startswith('Prochitecture Streets / Ordinary cyclic quad counts v1')
            and not any(tag in tree.name for tag in ('Original span sides', 'Original chain sides',
                                                     'Direct strip center'))
            and any(node.label == 'Count complete sides while retaining every curvature knot'
                    for node in tree.nodes))


def build(original):
    if not supports(original):
        raise ValueError('Expected an ordinary cyclic count kernel')
    name = original.name + ' / Grouped count experiment v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    continuations = 'Curb continuations' in original.name
    length_budget = 'Reserved contact primitive' in original.name
    lead_reservations = 'Reserved lead intervals' in original.name
    if length_budget and not continuations:
        raise ValueError('Reserved contact counts require continuation sides')
    g = c.Graph(name)
    for socket in original.interface.items_tree:
        if socket.item_type == 'SOCKET':
            g.socket(socket.name, socket.socket_type, socket.in_out,
                     default=getattr(socket, 'default_value', None))
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    index = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    mouths = inp.outputs['Mouths']; corners = inp.outputs['Corners']
    sides = c._count(g, mouths)
    cell = c.V(g, inp.outputs['Cell Size']); safe_cell = g.math('MAXIMUM', cell, .02)
    valid = c.V(g, inp.outputs['Input Valid'])*g.math('GREATER_THAN', sides, 2.5)
    valid *= g.math('LESS_THAN', sides, cyclic.MAX_SIDES+.5)
    valid *= g.math('GREATER_THAN', cell, .0199)*g.math('COMPARE', c._count(g, corners), sides)
    nominal = .5*c.named(g, 'st_cj_width')*(1.+g.math('ABSOLUTE', c.named(g, 'st_cj_half', 'INT')))
    radial = g.math('MAXIMUM', 4., 4.*g.math('CEIL', c._stat(g, mouths, nominal, 'Max')/(4.*safe_cell)))

    def length(owner):
        nxt = g.math('MODULO', owner+1., sides)
        la = g.math('ABSOLUTE', c._read(g, mouths, 'st_cj_parameter', owner)-c._read(g, corners, 'st_cc_sa', owner))
        lb = g.math('ABSOLUTE', c._read(g, mouths, 'st_cj_parameter', nxt)-c._read(g, corners, 'st_cc_sb', owner))
        if continuations:
            from . import curved_continuation_nodes
            arc = curved_continuation_nodes.length(g, corners, owner)
        else:
            arc = c._read(g, corners, 'st_cc_radius', owner)*g.math('ABSOLUTE', c._read(g, corners, 'st_cc_sweep', owner))
        return la+arc+lb

    owner = c.named(g, 'st_cg_owner', 'INT')
    knots = c._select(g, inp.outputs['Depths'], c.named(g, 'st_cg_break', 'BOOLEAN')*
                      g.math('GREATER_THAN', owner, -.5)*g.math('LESS_THAN', owner, sides-.5))
    # Unique integer weights preserve original order within every owner, even
    # if the caller interleaves owners. Prepared depth tables are bounded at
    # 4096 samples; these keys are exact float32 integers for <=32 owners.
    ordered = g.node('GeometryNodeSortElements', 'Group knots without changing their order within a side')
    ordered.domain = 'POINT'
    g.bind(knots, ordered.inputs['Geometry'])
    g.bind(owner*(c._count(g, knots)+1.)+index, ordered.inputs['Sort Weight'])
    knots = ordered.outputs['Geometry']
    total = c._count(g, knots)
    following = g.math('MINIMUM', index+1., g.math('MAXIMUM', total-1., 0.))
    t = c.named(g, 'st_cg_t')
    next_owner = c._read(g, knots, 'st_cg_owner', following, 'INT')
    next_t = c.choose(g, g.math('COMPARE', owner, next_owner), c._read(g, knots, 'st_cg_t', following), t)
    intervals = g.math('CEIL', g.math('MAXIMUM', 0., next_t-t)*length(owner)/safe_cell)

    def grouped_sum(value, kind='FLOAT'):
        node = g.node('GeometryNodeAccumulateField', 'Sum every retained knot interval for its original side')
        node.domain = 'POINT'; node.data_type = kind
        g.bind(owner, node.inputs['Group ID']); g.bind(value, node.inputs['Value'])
        return node.outputs['Total']

    values = [('_bc_base', grouped_sum(intervals), 'FLOAT'),
              ('_bc_knots', grouped_sum(1, 'INT'), 'INT')]
    if length_budget:
        from .curved_contact_mesh_station_nodes import contact_join
        values.append(('_bc_joins', grouped_sum(contact_join(g, corners, mouths, owner, t)), 'FLOAT'))
    # Capture every field on the same sorted knot geometry before using the
    # grouped records as lookup data. No temporary attributes reach the output.
    for key, value, kind in values:
        knots = c._store(g, knots, key, value, kind)
    keys = g.setpos(knots, g.xyz(owner, 0., 0.))
    nearest = g.node('GeometryNodeSampleNearest', 'Exact side identity for grouped count totals')
    nearest.domain = 'POINT'
    g.bind(keys, nearest.inputs['Geometry']); g.bind(g.xyz(index, 0., 0.), nearest.inputs['Sample Position'])
    at = nearest.outputs['Index']
    found = g.math('GREATER_THAN', total, .5)*g.math('COMPARE', c._read(g, keys, 'st_cg_owner', at, 'INT'), index)
    read = lambda key, kind='FLOAT': c.choose(g, found, c._read(g, keys, key, at, kind), 0, kind)
    count = read('_bc_knots', 'INT'); side_length = length(index)
    base = read('_bc_base')
    points = g.node('GeometryNodePoints', 'One count record per original side')
    g.bind(c.choose(g, valid, sides, 0, 'INT'), points.inputs['Count'])
    mesh = g.node('GeometryNodePointsToVertices'); g.bind(points.outputs['Points'], mesh.inputs['Points'])
    remove = g.node('GeometryNodeRemoveAttribute', 'Keep the original count-table attribute schema')
    remove.inputs['Name'].default_value = 'radius'; g.bind(mesh.outputs['Mesh'], remove.inputs['Geometry'])
    records = remove.outputs['Geometry']
    for key, value, kind in (('owner', index, 'INT'), ('length', side_length, 'FLOAT'),
                            ('base', base, 'INT'), ('knots', count, 'INT')):
        records = c._store(g, records, 'st_cq_'+key, value, kind)
    if length_budget:
        has_join = g.math('MINIMUM', 1., read('_bc_joins'))
        capacity = g.math('CEIL', side_length/safe_cell)+count-1.-has_join
        if lead_reservations:capacity += 1.
        records = c._store(g, records, 'st_cq_capacity', capacity, 'INT')
    attribute = 'st_cq_capacity' if length_budget else 'st_cq_base'
    needed = 2.*g.math('CEIL', g.math('MAXIMUM', g.math('MAXIMUM', 8., radial*.5+2.),
                                    c._stat(g, records, c.named(g, attribute, 'INT'), 'Max'))*.5)
    records = c._store(g, records, 'st_cq_count', needed, 'INT')
    budget = sides*((needed*.5+1.)**2.+(needed+1.)*(radial+1.))
    valid *= g.math('LESS_THAN', needed+1., cyclic.four.MAX_ROWS+.5)
    valid *= g.math('LESS_THAN', budget, cyclic.four.MAX_VERTICES+.5)
    for key, value in (('Geometry', records), ('Valid', valid), ('Radial Count', radial), ('Side Count', sides)):
        g.bind(value, out.inputs[key])
    g.g['st_batched_count_experiment'] = 1
    return g.g


def copy_graph(root):
    """Copy callers of supported count kernels; never modify the saved graph."""
    memo = {}; proof = []
    def visit(tree):
        if tree in memo:return memo[tree]
        if supports(tree):
            result = build(tree)
            proof.append(dict(original=tree.name, candidate=result.name))
        else:
            children = [(node.name, visit(node.node_tree)) for node in tree.nodes
                        if node.type == 'GROUP' and node.node_tree]
            children = [(name, child) for name, child in children if child != tree.nodes[name].node_tree]
            result = tree.copy() if children else tree
            if children:
                result.name = 'Qualification / Grouped count dependency / '+hashlib.sha256(tree.name.encode()).hexdigest()[:16]
                for name, child in children:assign_group(result.nodes[name], child)
        memo[tree] = result
        return result
    result = visit(root)
    if not proof:raise ValueError('No supported count kernels found')
    return result, proof
